% \endgroup
% \end{landscape}
% \pagestyle{fancy}

% ==============================================================================
% BLOQUE OPCIONAL: PRODUCTO VISUAL EN TIKZ
% Usar para mapa conceptual, mapa mental, diagrama, flujo, esquema o proceso.
% Cada flecha debe expresar relacion; no usar nodos sueltos sin conectores.
% ==============================================================================
