\subsection{Analisis propio}

\pendiente{Explicar que muestra el producto, que criterio se sostiene y que aprendizaje se obtiene. Esta parte evita que el documento sea solo una recopilacion.}

% ==============================================================================
% SECCION 3: POSTURA PERSONAL
% Debe mostrar comprension real. No repetir fuentes; interpretar.
% ==============================================================================
\section{Postura personal}

\pendiente{Redactar una postura academica y moderada. Relacionar el tema con claridad, responsabilidad comunicativa, precision academica, educacion a distancia o practica profesional.}

% ==============================================================================
% SECCION 4: CONCLUSION
% Cierre recomendado:
% - Responder directamente a la actividad.
% - Indicar que se comprendio, no solo que se elaboro.
% - Mencionar criterio personal final.
% - No introducir informacion nueva.
% ==============================================================================
\section{Conclusion}

\pendiente{Cerrar con sintesis, aprendizaje y postura final.}

